using System.Text;

namespace SedeImport;

/// <summary>
/// The T-SQL scripts of database/sede/ (decision 208), written after the pattern of
/// database/fiben/: tables and keys, the bulk load of the dump through staging tables of text,
/// and the foreign keys declared once after the load. The {{schema}} placeholder is dbo in the
/// Sede database of the container; batches are separated by GO.
/// </summary>
public static class Scripts
{
    private const string Header =
        """
        -- Generated by SedeImport from tables_so.json of hirupert/sede (Apache-2.0) and the schema
        -- documentation of SEDE; do not edit by hand - change the tool and run it again. Decision 208.
        """;

    public static string Schema(Schema schema)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- The tables of the SEDE schema with their primary keys: Id everywhere, PostId and TagId
            -- on PostTags. The foreign keys are in constraints.sql, which runs after load.sql. The
            -- columns are those of tables_so.json of the SEDE repository, the types those of the
            -- listing of the SEDE catalog where the import had it (SedeImport/Schema/types.csv) and
            -- otherwise provisional, from the categories of tables_so.json (the header of the file
            -- says which). Nothing is indexed beyond the keys. Eight tables are loaded from the data
            -- dump, PostTags is derived from Posts.Tags, the type tables are filled from the
            -- documentation, and the rest - review tasks, suggested edits, pending flags, post
            -- notices - stay empty: the dump does not carry them.
            --
            -- Batches are separated by a line containing only GO; the {{schema}} placeholder is dbo
            -- in the Sede database of the container.
            """);
        text.AppendLine($"-- Types: {(schema.TypesFromListing ? "from the listing of the SEDE catalog" : "provisional, from the categories of tables_so.json")}.");

        foreach (var table in schema.Tables)
        {
            text.AppendLine();
            text.AppendLine($"CREATE TABLE [{{{{schema}}}}].[{table.Name}] (");
            foreach (var column in table.Columns)
            {
                text.AppendLine($"    [{column.Name}] {column.SqlType} {(column.Nullable ? "NULL" : "NOT NULL")},");
            }

            text.AppendLine($"    CONSTRAINT [PK_{table.Name}] PRIMARY KEY ({string.Join(", ", table.Key.Select(part => $"[{part}]"))})");
            text.AppendLine(");");
            text.AppendLine("GO");
        }

        return text.ToString();
    }

    public static string Constraints(Schema schema)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- The foreign keys of the SEDE schema as the official documentation links them (answer
            -- 2678 on meta.stackexchange.com: a column written as a link to the table it references),
            -- run after schema.sql and, in the container, after the data is loaded. The catalog reads
            -- relations from exactly these declarations (decision 015); Stack Exchange declares them
            -- nowhere else. They are declared WITH NOCHECK: the dump of a site is a cut of the live
            -- data - deleted posts and deleted users are not in it while the rows that pointed at them
            -- are -, so a checked constraint would refuse the data the texts were written over, and
            -- the data stays as the dump has it.
            """);

        foreach (var key in schema.ForeignKeys)
        {
            text.AppendLine();
            text.AppendLine($"ALTER TABLE [{{{{schema}}}}].[{key.Table}] WITH NOCHECK ADD");
            text.AppendLine($"    CONSTRAINT [FK_{key.Table}_{key.Column}] FOREIGN KEY ([{key.Column}]) REFERENCES [{{{{schema}}}}].[{key.ReferencedTable}] ([Id]);");
            text.AppendLine("GO");
        }

        return text.ToString();
    }

    public static string Load(Schema schema)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine(
            """
            --
            -- Loads the data dump of one site into the tables of schema.sql. Run by sqlcmd between
            -- schema.sql and constraints.sql with one variable, DataPath: the directory holding one
            -- <Table>.csv per dumped table, as xml-to-csv.py writes them from the XML of the dump
            -- (dump.tsv says which tables and columns), as a path the database server itself can
            -- read, since BULK INSERT runs there.
            --
            -- The files are CSV with every field in double quotes, a quote doubled, an absent
            -- attribute as an empty field (NULL), a date as yyyy-mm-ddThh:mm:ss.fff and a flag as
            -- True or False; UTF-8 without a header. Every file goes into a staging table of text
            -- first and is converted from there, so a malformed value fails with the name of the
            -- table; the staging columns are VARCHAR in a UTF-8 collation and the files are read with
            -- CODEPAGE = 'RAW', the one form SQL Server on Linux accepts. PostTags is then derived
            -- from Posts.Tags as SEDE derives it, the type tables are filled from the documentation,
            -- and the staging schema is dropped.
            --
            -- The {{schema}} placeholder works as in schema.sql.

            SET NOCOUNT ON;
            SET XACT_ABORT ON;
            GO

            IF SCHEMA_ID('sede_load') IS NULL EXEC (N'CREATE SCHEMA [sede_load]');
            GO
            """);

        foreach (var table in schema.Tables.Where(table => table.DumpFile is not null))
        {
            var staged = string.Join(", ", table.Columns.Select(column => $"[{column.Name}] VARCHAR(MAX) COLLATE Latin1_General_100_BIN2_UTF8"));
            text.AppendLine();
            text.AppendLine($"CREATE TABLE [sede_load].[{table.Name}] ({staged});");
            text.AppendLine($"BULK INSERT [sede_load].[{table.Name}] FROM '$(DataPath)/{table.Name}.csv' WITH (FORMAT = 'CSV', FIELDQUOTE = '\"', FIELDTERMINATOR = ',', ROWTERMINATOR = '0x0a', CODEPAGE = 'RAW', TABLOCK);");
            text.AppendLine($"INSERT INTO [{{{{schema}}}}].[{table.Name}] WITH (TABLOCK) ({string.Join(", ", table.Columns.Select(column => $"[{column.Name}]"))})");
            text.AppendLine($"SELECT {string.Join(", ", table.Columns.Select(column => column.Conversion($"[{column.Name}]")))}");
            text.AppendLine($"FROM [sede_load].[{table.Name}];");
            text.AppendLine($"DROP TABLE [sede_load].[{table.Name}];");
            text.AppendLine("GO");
        }

        text.AppendLine();
        text.AppendLine(
            """
            -- PostTags as SEDE derives it: one row per tag of a question, the tag found by its name.
            -- The converter writes Posts.Tags in the spelling of SEDE, <tag><tag>, whatever the dump's.
            INSERT INTO [{{schema}}].[PostTags] WITH (TABLOCK) ([PostId], [TagId])
            SELECT DISTINCT p.[Id], t.[Id]
            FROM [{{schema}}].[Posts] p
            CROSS APPLY STRING_SPLIT(REPLACE(REPLACE(p.[Tags], '><', ','), '<', ''), ',') s
            INNER JOIN [{{schema}}].[Tags] t ON t.[TagName] = REPLACE(s.[value], '>', '')
            WHERE p.[Tags] IS NOT NULL;
            GO
            """);

        foreach (var enumeration in schema.Enumerations)
        {
            text.AppendLine();
            text.AppendLine($"-- {enumeration.Table}, as the documentation lists it.");
            text.AppendLine($"INSERT INTO [{{{{schema}}}}].[{enumeration.Table}] ([Id], [Name]) VALUES");
            text.AppendLine(string.Join(",\n", enumeration.Values.Select(value => $"    ({value.Id}, N'{value.Name.Replace("'", "''")}')")) + ";");
            text.AppendLine("GO");
        }

        text.AppendLine();
        text.AppendLine("DROP SCHEMA [sede_load];");
        text.AppendLine("GO");

        return text.ToString();
    }

    /// <summary>The tables the converter reads from the dump and the columns it writes, in the order load.sql stages them: table, file, columns.</summary>
    public static string Dump(Schema schema)
    {
        var text = new StringBuilder();
        foreach (var table in schema.Tables.Where(table => table.DumpFile is not null))
        {
            text.Append(table.Name).Append('\t').Append(table.DumpFile).Append('\t').Append(string.Join(',', table.Columns.Select(column => column.Name))).Append('\n');
        }

        return text.ToString();
    }

    /// <summary>
    /// The Dapper entity class of one table (decision 208): properties named as the columns are,
    /// typed as the schema says, nothing else. A Dapper source states no key, relation or
    /// length; every such fact comes from the catalog of the Sede database.
    /// </summary>
    public static string Entity(Table table)
    {
        var text = new StringBuilder();
        text.AppendLine("namespace Sede;");
        text.AppendLine();
        text.AppendLine($"public class {table.Name}");
        text.AppendLine("{");

        var first = true;
        foreach (var column in table.Columns)
        {
            if (!first)
            {
                text.AppendLine();
            }

            first = false;
            text.AppendLine($"    public {column.CSharpType} {column.Name} {{ get; set; }}");
        }

        text.AppendLine("}");
        return text.ToString();
    }
}
